mapper.select:
SELECT s.id, s.title, s.updated_at, 
WHERE s.project_id = #{projectId}
ORDER BY s.updated_at DESC, s.id ASC

mapper.update:
UPDATE sessions SET title = #{title}, updated_at = MAX(updated_at + 1, #{updatedAt}),
                    revision = revision + CASE WHEN title = #{title} THEN 0 ELSE 1 END
WHERE id = #{sessionId}
